'use strict';
const root=document.querySelector('#app');
let profile=null,monthlyData=null,cardDebtData=null,selectedMonth=dayMonth(),loadRevision=0;
let selectedDebtMonth='';try{selectedDebtMonth=sessionStorage.getItem('finance.debt-month')||''}catch{}
function chooseDebtMonth(value){selectedDebtMonth=value;try{sessionStorage.setItem('finance.debt-month',value)}catch{}}
function dayMonth(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit'}).formatToParts(new Date());return parts.find(p=>p.type==='year').value+'-'+parts.find(p=>p.type==='month').value}
let csrf='',privateBeta=false,section='overview',data=null,options={categories:[],payment_methods:[],credit_cards:[]};
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const plusMonths=(value,count)=>{const [y,m,d]=value.split('-').map(Number),date=new Date(Date.UTC(y,m-1+count,1));return new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).toISOString().slice(0,10)};
let start=day().slice(0,7)+'-01',end=plusMonths(day(),3);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>{const amount=BigInt(value||0),absolute=amount<0n?-amount:amount;return `${amount<0n?'−':''}${(absolute/100n).toLocaleString('tr-TR')},${String(absolute%100n).padStart(2,'0')} ₺`};
const inputMoney=value=>{const n=BigInt(value||0);return `${n/100n}.${String(n%100n).padStart(2,'0')}`};
const dateLabel=value=>value?new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul'}).format(new Date(value+'T12:00:00Z')):'—';
const statusLabel=value=>({received:'Alındı',expected:'Bekleniyor',planned:'Planlandı',paid:'Ödendi',overdue:'Gecikmiş',completed:'Kaydedildi'}[value]||value);
async function api(path,settings={}){const response=await fetch(path,{...settings,headers:{'Content-Type':'application/json',...(settings.method&&settings.method!=='GET'?{'X-CSRF-Token':csrf}:{}),...(settings.headers||{})}});let result={};try{result=await response.json()}catch{}if(response.status===401){authView();throw Error('Oturum açmanız gerekiyor.')}if(!response.ok)throw Error(result.error||'İşlem tamamlanamadı. Lütfen tekrar deneyin.');return result}
function themeToggleMarkup(){const dark=document.documentElement?.dataset?.theme!=='light';return `<button type="button" class="theme-toggle" data-theme-toggle aria-label="${dark?'Açık temaya geç':'Koyu temaya geç'}" title="${dark?'Açık temaya geç':'Koyu temaya geç'}" aria-pressed="${dark}"><span class="theme-icon" aria-hidden="true">${dark?'🌙':'☀️'}</span><span class="theme-label">${dark?'Koyu tema':'Açık tema'}</span></button>`}
function authView(register=false){root.innerHTML=`<section class="auth">${themeToggleMarkup()}<div class="brandmark">₺</div><p class="eyebrow">KİŞİSEL BÜTÇE</p><h1>Kontrol sizde.</h1><p class="muted">Gelirlerinizi, taksitlerinizi ve ödeme sonrası kalan tutarı takip edin.</p><form id="auth-form"><label>E-posta<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Parola<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="10" required><small>En az 10 karakter</small></label>${register&&privateBeta?'<label>Davet kodu<input name="invitation_token" required></label>':''}<button class="primary">${register?'Hesap oluştur':'Giriş yap'}</button><p id="auth-error" class="error" role="alert"></p></form><button class="link" id="toggle-auth">${register?'Giriş yap':'Hesap oluştur'}</button></section>`;document.querySelector('#toggle-auth').onclick=()=>authView(!register);document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');if(button.disabled)return;button.disabled=true;try{const result=await api(register?'/api/register':'/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});csrf=result.csrf;await load()}catch(error){const target=document.querySelector('#auth-error');if(target)target.textContent=error.message}finally{button.disabled=false}}}
async function load(){const revision=++loadRevision;root.setAttribute('aria-busy','true');try{const query=new URLSearchParams({start,end}),values=await Promise.all([api('/api/options'),api('/api/simple-cashflow?'+query),api('/api/profile'),api('/api/simple-cashflow?'+new URLSearchParams({start:selectedMonth+'-01',end:plusMonths(selectedMonth+'-01',0)}))]);if(revision!==loadRevision)return;const [nextOptions,nextData,nextProfile,nextMonthly]=values;const upcoming=(nextProfile.cards||[]).filter(card=>card.active&&card.payment_due_on&&card.payment_due_on>=day()).map(card=>card.payment_due_on).sort();const debtMonth=selectedDebtMonth||upcoming[0]?.slice(0,7)||selectedMonth;const nextDebt=debtMonth===selectedMonth?nextMonthly:await api('/api/simple-cashflow?'+new URLSearchParams({start:debtMonth+'-01',end:plusMonths(debtMonth+'-01',0)}));if(revision!==loadRevision)return;[options,data,profile,monthlyData,cardDebtData]=[nextOptions,nextData,nextProfile,nextMonthly,nextDebt];render()}catch(error){if(revision!==loadRevision||document.querySelector('#auth-form'))return;const banner=document.querySelector('#action-error');if(banner)banner.textContent=error.message;else root.innerHTML=`<section class="auth"><h1>Plan yüklenemedi.</h1><p class="error">${esc(error.message)}</p><button id="retry" class="primary">Tekrar dene</button></section>`;const retry=document.querySelector('#retry');if(retry)retry.onclick=load}finally{if(revision===loadRevision)root.setAttribute('aria-busy','false')}}
function eventKindLabel(event){if(event.monthly_card_ref)return 'Aylık kart borcu';if(event.kind==='income')return 'Gelir';if(event.kind==='adjustment')return 'Bakiye düzeltmesi';if(event.statement_id)return 'Kart ekstresi';const rule=data?.rules?.find(rule=>rule.id===event.recurring_id);if(rule)return rule.entry_kind==='regular'?'Banka / nakit düzenli ödeme':rule.entry_kind==='expense'?'Tek seferlik kart harcaması':'Taksit';return event.id.startsWith('repayment:')?'Kart ödemesi':'Ödeme'}
function eventRows(events){return events.length?events.map(event=>`<article class="planned-row"><div><b>${esc(event.description)}</b><small>${dateLabel(event.date)} · ${eventKindLabel(event)} · ${statusLabel(event.status)}</small></div><strong class="${event.kind==='income'?'income-amount':''}">${BigInt(event.cash_effect_minor)>=0n?'+':'−'}${money(BigInt(event.amount_minor)<0n?-BigInt(event.amount_minor):event.amount_minor)}</strong>${event.kind==='payment'&&event.status!=='paid'&&(event.recurring_id||event.statement_id||event.monthly_card_ref)?`<button class="secondary compact" data-pay="${esc(event.id)}">Ödedim</button>`:''}${event.kind==='income'&&event.status!=='received'?`<button class="secondary compact" data-receive="${esc(event.id)}">Alındı</button>`:''}</article>`).join(''):'<p class="muted">Bu tarihler arasında kayıt yok.</p>'}
function savedPaymentsOverviewMarkup(){const rules=(data.rules||[]).filter(rule=>rule.status!=='cancelled');return `<section class="panel saved-payments-overview"><div class="panel-head"><div><h2>Kayıtlı ödemelerim</h2><p class="muted">Ödemelerim bölümündeki tüm kayıtlar. ${esc(monthLabel(selectedMonth))} tutarı her satırda ayrıca gösterilir.</p></div><a class="link" href="#payments" data-section="payments">Ödemelerimi düzenle →</a></div><div class="rule-list">${rules.map(rule=>{const scheduled=monthlyData?.rules?.find(item=>item.id===rule.id)?.scheduled_total_minor,monthly=scheduled!==undefined?BigInt(scheduled):(monthlyData?.events||[]).filter(event=>event.recurring_id===rule.id).reduce((sum,event)=>sum+BigInt(event.amount_minor),0n);return `<article class="rule-row"><div class="rule-info"><b>${esc(rule.description)}</b><small>${esc(paymentLabel(rule))} · ${rule.entry_kind==='expense'?'Tek seferlik':rule.frequency==='weekly'?'Haftalık':rule.frequency==='yearly'?'Yıllık':'Aylık'} ${money(rule.amount_minor)}</small><small>İlk ödeme ${dateLabel(rule.display_start_on||rule.start_on)}${rule.end_on?' · Son ödeme '+dateLabel(rule.display_end_on||rule.end_on):''}${rule.status==='paused'?' · Duraklatıldı':''}</small></div><span class="payment-month-badge">${monthly!==0n?(scheduled!==undefined?'Bu ayki plan ':'Bu ay ')+money(monthly):'Seçili ayda ödeme yok'}</span></article>`}).join('')||'<p class="muted">Henüz kayıtlı ödeme planı yok.</p>'}</div></section>`}
function statementOverviewMarkup(){const statements=(data.statements||[]).filter(row=>BigInt(row.total_minor)>0n&&!row.covered_by_monthly_total),outstanding=statements.reduce((sum,row)=>sum+BigInt(row.remaining_minor),0n);if(!statements.length)return '';return `<section class="panel statement-overview"><div class="panel-head"><div><h2>Kredi kartı ekstreleri</h2><p class="muted">Kayıtlı kart borçların. Aylık nakit ödemeye son ödeme tarihinde dahil edilir.</p></div><div class="statement-total"><small>ÖDENMEMİŞ KART BORCU</small><strong>${money(outstanding)}</strong></div></div><div class="rule-list">${statements.map(row=>`<article class="rule-row"><div class="rule-info"><b>${esc(row.description)}</b><small>Son ödeme ${dateLabel(row.due_on)} · ${BigInt(row.remaining_minor)===0n?'Ödendi':'Ödeme bekliyor'}</small><small>Ekstre ${money(row.total_minor)} · Ödenen ${money(row.paid_minor)}</small></div><strong>${money(row.remaining_minor)}</strong>${BigInt(row.remaining_minor)>0n?`<button class="secondary compact" data-pay="statement:${row.id}">Ödedim</button>`:''}</article>`).join('')||'<p class="muted">Henüz kayıtlı ekstre yok.</p>'}</div></section>`}
function cashBalanceMarkup(){const position=monthlyData?.cash_position||data?.cash_position;if(position?.balance_minor!==null&&position?.balance_minor!==undefined)return `<section class="cash-balance-card"><div><p class="eyebrow">BANKA / NAKİT BAKİYESİ</p><strong>${money(position.balance_minor)}</strong><p class="muted">${dateLabel(position.as_of)} itibarıyla kayıtlara göre. Başlangıç: ${money(position.opening_balance_minor)} · ${dateLabel(position.effective_on)}</p><small>Bu tutar gelir değildir. Yalnızca alınan gelir ve gerçekleşen ödemeler bakiyeyi değiştirir.</small></div><button class="secondary compact" id="new-opening">Başlangıç bakiyesini düzenle</button></section>`;return `<section class="cash-balance-card"><div><p class="eyebrow">BANKA / NAKİT BAKİYESİ</p><h2>Başlangıç bakiyesi tanımlanmadı</h2><p class="muted">Hesabındaki mevcut parayı gelir eklemeden ayrı kaydet.</p></div><button class="secondary compact" id="new-opening">Bakiye tanımla</button></section>`}
function monthLabel(value){return new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',month:'long',year:'numeric'}).format(new Date(value+'-01T12:00:00Z'))}
function summaryCards(view,monthly=false){const totals=view.totals,income=BigInt(totals.income_received_minor)+BigInt(totals.income_expected_minor),payments=BigInt(totals.payments_paid_minor)+BigInt(totals.payments_planned_minor),projected=view.cash_position?.projected_balance_minor,hasProjection=projected!==null&&projected!==undefined;return `<section class="stats ${monthly?'monthly-stats':'overall-stats'}" aria-label="${monthly?'Seçili ayın toplamları':'Genel toplamlar'}"><article class="stat"><span>${monthly?'Aylık gelirler':'Toplam gelirler'}</span><strong>${money(income)}</strong><small>Alınan ${money(totals.income_received_minor)} · Beklenen ${money(totals.income_expected_minor)}</small></article><article class="stat spend"><span>${monthly?'Aylık ödemeler':'Toplam ödemeler'}</span><strong>${money(payments)}</strong><small>Ödenen ${money(totals.payments_paid_minor)} · Planlanan ${money(totals.payments_planned_minor)}</small></article><article class="stat"><span>${hasProjection?(monthly?'Ay sonu öngörülen bakiye':'Plan sonunda öngörülen bakiye'):(monthly?'Aylık kalan':'Plan sonunda kalan')}</span><strong>${money(hasProjection?projected:view.net_minor)}</strong><small>${hasProjection?'Mevcut banka/nakit bakiyesi + dönem sonuna kadar beklenen gelirler − ödenmemiş planlanan ödemeler. Geçmişten kalan bekleyen kayıtlar dahildir.':monthly?'Gelir − ödemeler. Başlangıç bakiyesi hariçtir.':'Alınan ve beklenen gelirler − ödenen ve planlanan ödemeler. Mevcut banka bakiyesi değildir.'}${BigInt(totals.adjustments_minor)!==0n?` Bakiye düzeltmeleri: ${money(totals.adjustments_minor)}.`:''}</small></article></section>`}
function overviewMarkup(){return `<section class="monthly-heading"><div><p class="eyebrow">AYLIK ÖZET</p><h2>${esc(monthLabel(selectedMonth))}</h2></div><div class="month-navigation"><button class="secondary compact" id="previous-month" aria-label="Önceki ay">‹</button><label><span class="sr-only">Özet ayı</span><input id="overview-month" type="month" value="${selectedMonth}" aria-label="Özet ayı"></label><button class="secondary compact" id="next-month" aria-label="Sonraki ay">›</button><button class="link" id="current-month">Bu ay</button></div></section>${summaryCards(monthlyData,true)}${savedPaymentsOverviewMarkup()}${extraSpendingMarkup()}${statementOverviewMarkup()}${cashBalanceMarkup()}<section class="overall-summary"><div class="overall-heading"><h2>Genel toplamlar</h2><p>${dateLabel(start)} – ${dateLabel(end)} · Seçili tarih aralığının tamamı</p></div>${summaryCards(data)}</section><section class="panel"><div class="panel-head"><div><h2>Gelir ve ödeme takvimi</h2><p class="muted">${esc(monthLabel(selectedMonth))} ayındaki gelir ve ödemeler. Planlanan ve gerçekleşen tutarlar ayrı gösterilir.</p></div><div class="simple-actions"><button class="secondary compact" id="new-income">Gelir ekle</button><button class="primary compact" id="new-payment">Taksit / harcama ekle</button></div></div><div class="planned-list">${eventRows(monthlyData.events)}</div></section>`}
function shiftOverviewMonth(offset){const [year,month]=selectedMonth.split('-').map(Number),date=new Date(Date.UTC(year,month-1+offset,1));selectedMonth=date.toISOString().slice(0,7);load()}
function findEvent(id){const event=[...(cardDebtData?.events||[]),...(monthlyData?.events||[]),...data.events].find(row=>row.id===id);if(event)return event;const statement=data.statements?.find(row=>'statement:'+row.id===id);return statement?{...statement,id:'statement:'+statement.id,statement_id:statement.id,amount_minor:statement.remaining_minor,scheduled_on:statement.due_on,date:statement.due_on,kind:'payment'}:null}
function cardLabel(reference){const card=profile?.cards.find(card=>card.id===reference);return card?`${card.bank_name} · ${card.display_name}`:'Banka / nakit'}
function paymentLabel(rule){if(rule.card_ref)return cardLabel(rule.card_ref);if(rule.entry_kind==='regular')return rule.frequency==='weekly'?'Banka / nakit · Haftalık':'Banka / nakit · Aylık';const method=options.payment_methods?.find(method=>String(method.id)===String(rule.payment_method_id));return method?.name?method.name+(/kredi/i.test(method.name)?' · Kart seçilmedi':''):'Ödeme yöntemi belirtilmedi'}
function paymentKindLabel(kind){return {installment:'Kartların aylık taksidi',regular:'Nakit olarak düzenli ödeme',expense:'Ekstreye yansıyan ek harcamalar'}[kind]||'Ödeme'}
function cardDuePreview(card,month,offset=0){const [year,m]=month.split('-').map(Number),last=new Date(Date.UTC(year,m,0)).getUTCDate(),value=new Date(Date.UTC(year,m-1,Math.min(card.payment_due_day,last)+Number(offset)));return value.toISOString().slice(0,10)}
function invoiceDueInput(card,month){return card.due_on||card.configured_due_on||cardDuePreview(card,month,card.due_day_offset||0)}
function extraSpendingMarkup(){const debtView=cardDebtData||monthlyData,debtMonth=debtView?.card_monthly_debt?.month||selectedDebtMonth||selectedMonth;const debt=debtView?.card_monthly_debt||{cards:[],unassigned_installments:[],extra_minor:'0'},budget=debtView?.extra_budget;const remaining=budget?BigInt(budget.income_minor)-BigInt(budget.fixed_minor)-BigInt(debt.extra_minor):0n;return `<section class="panel extra-spending"><div class="panel-head"><div><p class="eyebrow">${esc(monthLabel(debtMonth))} · KART EKSTRELERİ</p><h2>Ekstreye yansıyan ek harcamalar</h2><p class="muted">Toplam borçtan, son ödeme tarihinin bulunduğu ayın taksit ve düzenli kart ödemeleri çıkarılır. Bu bölüm Genel Bakış ayından bağımsızdır.</p></div><label>Ekstre ödeme ayı<input type="month" id="spending-month" value="${debtMonth}" aria-label="Ekstre ödeme ayı"></label></div>${budget?`<div class="extra-budget"><article><span>Ek harcamalar için kalan pay</span><strong>${money(budget.allowance_minor)}</strong><small>Aylık gelir ${money(budget.income_minor)} − taksit ve düzenli ödemeler ${money(budget.fixed_minor)}</small></article><article><span>Hesaplanan ek harcamalar</span><strong>${money(debt.extra_minor)}</strong><small>${debt.complete?'Tüm kartlar hesaplandı':'Yalnızca hesaplanabilen kartlar'}</small></article><article class="${debt.complete&&remaining<0n?'budget-over':'budget-available'}"><span>${debt.complete?(remaining<0n?'Gelire göre açık':'Ek harcamalar sonrası kalan pay'):'Kalan pay henüz hesaplanamadı'}</span><strong>${debt.complete?money(remaining<0n?-remaining:remaining):'Eksik bilgi'}</strong><small>${!debt.complete?'Kart toplamlarını ve eksik taksit bağlantılarını tamamla.':remaining<0n?'Ek harcamalar ve sabit ödemeler gelirini bu tutarda aşıyor.':'Alınan ve beklenen gelire göre. Banka bakiyesi hariç.'}</small></article></div>`:''}${debt.unassigned_installments.length?`<p class="budget-warning">${debt.unassigned_installments.length} taksidin kartı seçilmemiş. Doğru ek harcama hesabı için Ödemelerim bölümünde bu taksitlerin kartını seç: ${debt.unassigned_installments.map(row=>esc(row.description)).join(', ')}. Kart bağlantıları tamamlanana kadar sonuç kesin değildir.</p>`:''}<div class="card-spending-list">${debt.cards.map(card=>`<article class="card-spending"><h3>${esc(card.bank_name)} · ${esc(card.display_name)}</h3><form class="card-total-form" data-card-total="${esc(card.card_ref)}"><label>Son ödeme günü<output class="date-summary">${dateLabel(card.due_on||card.configured_due_on)}</output><small>Kart ayarı: ayın ${card.payment_due_day}. günü</small></label><label>Kart Son Ödeme Günü Düzeltmesi<select name="due_day_offset" aria-describedby="due-offset-${esc(card.card_ref)}">${Array.from({length:11},(_,i)=>i-5).map(value=>`<option value="${value}" ${value===(card.due_day_offset||0)?'selected':''}>${value>0?'+':''}${value} gün</option>`).join('')}</select><small id="due-offset-${esc(card.card_ref)}">Yalnızca seçili ay için geçerlidir.</small></label><label>Bu ayki toplam ekstre borcu (₺)<input name="amount" type="number" min="0" step="0.01" required value="${card.total_minor===null?'':inputMoney(card.total_minor)}" placeholder="Toplam borcu gir"></label><button type="submit" class="secondary compact">Borcu kaydet</button><p class="error" role="alert"></p></form><div class="card-debt-parts"><span>Kartların aylık taksidi <b>${money(card.installment_minor)}</b></span><span>Düzenli kart ödemeleri <b>${money(card.regular_minor)}</b></span><span>Ekstreye yansıyan ek harcamalar <strong>${card.extra_minor===null?'Hesaplanamadı':money(card.extra_minor)}</strong></span></div>${card.remaining_minor!==null?`<p class="muted">Son ödeme ${dateLabel(card.due_on)} · Kalan borç ${money(card.remaining_minor)}</p>${BigInt(card.remaining_minor)>0n?`<button class="secondary compact" data-pay="card-month:${esc(card.card_ref)}:${esc(debtMonth)}">Ödedim</button>`:''}`:''}<small>${card.source==='entered'?'Girdiğin aylık toplam esas alındı.':card.source==='statement'?'Kayıtlı ekstre ve ödeme planlarından hesaplandı; toplamı güncelleyebilirsin.':'Bu ayın toplam borcunu gir.'}</small>${card.inconsistent?'<p class="budget-warning">Toplam borç, bu karta bağlı taksit ve düzenli ödemelerden düşük. Toplamı, taksitleri ve kart bağlantılarını kontrol et; negatif fark ek harcama sayılmaz.</p>':''}</article>`).join('')||'<p class="muted">Kartlarını Profil ve Ayarlar bölümünden tanımlayabilirsin.</p>'}</div><p class="muted budget-note">İleri aylardaki taksitlerin tamamını değil, seçili ayın toplam ekstre borcunu gir. Toplam borç, taksitler ve kayıtlı harcamalarla birlikte aylık ödeme planında yalnızca bir kez sayılır. Ödedim seçeneğiyle gerçekleşen ödeme kaydedilene kadar banka bakiyen değişmez.</p><button class="secondary compact" id="new-extra">Ek harcama ekle</button></section>`}
function paymentsMarkup(){const rules=(data.rules||[]).filter(rule=>rule.status!=='cancelled');return `<section class="panel"><div class="panel-head"><div><h2>Ödemelerim</h2><p class="muted">Taksitlerini, düzenli ödemelerini ve ek harcamalarını ayrı takip et.</p></div><button class="primary" id="new-payment">Taksit / harcama ekle</button></div>${['installment','regular','expense'].map(kind=>`<section class="payment-group"><h3>${paymentKindLabel(kind)}</h3>${kind==='regular'?'<p class="muted">Banka kartı, nakit veya kredi kartıyla yaptığın sabit ödemeler.</p>':''}<div class="rule-list">${rules.filter(rule=>(rule.entry_kind||'installment')===kind).map(rule=>`<article class="rule-row"><div class="rule-info"><b>${esc(rule.description)}</b><small>${money(rule.amount_minor)} · ${esc(paymentLabel(rule))}</small><small>${kind==='expense'?'Kart ödeme günü':'İlk ödeme'} ${dateLabel(rule.display_start_on||rule.start_on)}${kind!=='expense'&&rule.end_on?` · ${kind==='regular'?'Son ödeme':'Taksit bitişi'} ${dateLabel(rule.display_end_on||rule.end_on)}`:''}${rule.status==='paused'?' · Duraklatıldı':''}</small></div><div class="rule-actions"><button class="secondary compact" data-edit-rule="${rule.id}">Düzenle</button><button class="link danger-link" data-delete-kind="payment_plan" data-record-id="${rule.id}">Sil</button>${kind!=='expense'?`<button class="link" data-rule-status="${rule.id}" data-status="${rule.status==='active'?'paused':'active'}">${rule.status==='active'?'Duraklat':'Devam ettir'}</button>`:''}</div></article>`).join('')||'<p class="muted">Bu grupta henüz kayıt yok.</p>'}</div></section>`).join('')}</section>${extraSpendingMarkup()}${statementOverviewMarkup()}`}
function incomeMarkup(){const rules=(data.income_rules||[]).filter(row=>row.status!=='cancelled'),records=(data.income_records||[]).filter(row=>row.status!=='cancelled');return `<section class="panel"><div class="panel-head"><div><h2>Gelirlerim</h2><p class="muted">Gelir kayıtlarını ve düzenli planlarını düzenleyebilir veya silebilirsin.</p></div><button class="primary" id="new-income">Gelir ekle</button></div><div class="rule-list">${rules.map(row=>incomeManagementRow(row,'income_rule')).join('')}${records.map(row=>incomeManagementRow(row,'income_record')).join('')}${!rules.length&&!records.length?'<p class="muted">Henüz gelir kaydı yok.</p>':''}</div></section><section class="panel"><h2>Gelir takvimi</h2><p class="muted">Düzenli planların tarihleri otomatik oluşur. Düzenleme yukarıdaki kayıttan yapılır.</p><div class="planned-list">${eventRows(data.events.filter(event=>event.kind==='income'))}</div></section>`}
function incomeManagementRow(row,kind){const rule=kind==='income_rule';return `<article class="rule-row"><div class="rule-info"><b>${esc(row.description)}</b><small>${money(row.amount_minor)} · ${rule?(row.frequency==='weekly'?'Haftalık düzenli gelir':'Aylık düzenli gelir'):(row.rule_id?'Düzenli gelir tahsilatı':'Tek seferlik gelir')}</small><small>${rule?(row.schedule_mode==='last_day'?'Her ayın son günü · Başlangıç '+dateLabel(row.start_on):'İlk gelir '+dateLabel(row.start_on)):(row.status==='received'?'Alındı · '+dateLabel(row.received_on):'Bekleniyor · '+dateLabel(row.expected_on))}${rule&&row.status==='paused'?' · Duraklatıldı':''}</small></div><div class="rule-actions"><button class="secondary compact" data-edit-income="${row.id}" data-income-kind="${kind}">Düzenle</button><button class="link danger-link" data-delete-kind="${kind}" data-record-id="${row.id}">Sil</button></div></article>`}
function profileMarkup(){
  if(!profile)return '<section class="panel"><h2>Profil bilgileri yüklenemedi.</h2><p class="muted">Sayfayı yenileyip yeniden deneyin.</p></section>';
  return `<section class="panel"><div class="panel-head"><div><h2>Profil ve Ayarlar</h2><p class="muted">${esc(profile.email)}</p></div></div><form id="profile-form" class="profile-form"><label>Profil adı<input name="display_name" maxlength="80" value="${esc(profile.display_name)}" required></label><label>E-posta<input value="${esc(profile.email)}" type="email" readonly></label><p class="error" id="profile-error" role="alert"></p><button type="submit" class="secondary" disabled>Profili kaydet</button></form></section><section class="panel" id="profile-cards"><div class="panel-head"><div><h2>Kredi kartlarım</h2><p class="muted">Kartlarının her ay geçerli son ödeme gününü buradan yönet.</p></div><button class="primary" id="new-card">Kart tanımla</button></div><div class="rule-list">${profile.cards.map(card=>`<article class="rule-row"><div class="rule-info"><b>${esc(card.bank_name)} · ${esc(card.display_name)}</b><small>${card.last_four?'•••• '+esc(card.last_four)+' · ':''}${card.active?'Aktif':'Pasif'}</small><small>Son ödeme günü: Her ayın ${card.payment_due_day}. günü</small></div><button class="secondary compact" data-edit-profile-card="${esc(card.id)}">Düzenle</button></article>`).join('')||'<p class="muted">Henüz kart tanımlı değil.</p>'}</div></section>`;
}
function openCard(card){const form=document.querySelector('#card-form');form.reset();form.elements.id.value=card?.id||'';form.elements.version.value=card?.version??0;for(const key of ['bank_name','display_name','last_four','payment_due_day'])form.elements[key].value=card?.[key]||'';form.elements.active.value=String(card?.active??1);document.querySelector('#card-error').textContent='';document.querySelector('#card-dialog').showModal()}
function dialogHead(symbol,eyebrow,title,description){return `<div class="entry-heading"><span class="entry-symbol" aria-hidden="true">${symbol}</span><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2><p class="muted">${description}</p></div></div>`}
function dialogs(){return `<dialog id="delete-dialog" class="entry-dialog"><form id="delete-form">${dialogHead('−','KAYDI SİL','Bu kaydı silmek istiyor musun?','Silinen kaydı işlemden sonra Geri al ile geri getirebilirsin.')}<input name="record_kind" type="hidden"><input name="id" type="hidden"><input name="revision" type="hidden"><p id="delete-name"></p><p class="entry-hint" id="delete-impact"></p><p id="delete-error" class="error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-close="delete-dialog">Vazgeç</button><button class="danger-button" type="submit">Kaydı sil</button></div></form></dialog><dialog id="opening-dialog" class="entry-dialog"><form id="opening-form">${dialogHead('₺','BANKA / NAKİT','Başlangıç bakiyesi','Hesabındaki mevcut para; gelir olarak sayılmaz.')}<input name="revision" type="hidden"><label>Mevcut tutar (₺)<input name="amount" type="number" step="0.01" min="0" required></label><label>Bakiyenin geçerli olduğu tarih<input name="effective_on" type="date" max="${day()}" required></label><p class="entry-hint">Seçtiğin tarihten sonraki alınan gelirler ve gerçek ödemeler bu bakiyeyi günceller. Başlangıç tutarını veya tarihini düzelttiğinde bakiye yeniden hesaplanır; gelir oluşturulmaz.</p><p id="opening-error" class="error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-close="opening-dialog">Vazgeç</button><button type="submit" class="primary">Bakiyeyi kaydet</button></div></form></dialog><dialog id="payment-dialog" class="entry-dialog"><form id="payment-form">${dialogHead('↗','ÖDEMELERİM','<span id="payment-title">Taksit / harcama ekle</span>','Ödeme türünü seç, planını netleştir.')}<input name="id" type="hidden"><input name="request_key" type="hidden"><div class="entry-fields"><label class="field-wide">İşlem türü<select name="entry_kind"><option value="installment">Kartların aylık taksidi</option><option value="expense">Ekstreye yansıyan ek harcamalar</option><option value="regular">Nakit olarak düzenli ödeme</option></select></label><label class="field-wide">Açıklama<input name="description" placeholder="Örn. telefon taksidi veya market alışverişi" maxlength="160" required></label><label class="field-wide" id="payment-card-field">Kredi kartı<select name="card_ref"></select><small id="payment-card-help">Kartlarını Profil ve Ayarlar bölümünden yönetebilirsin.</small></label><label class="field-wide amount-field"><span id="payment-amount-label">Aylık taksit tutarı (₺)</span><input name="amount" type="number" inputmode="decimal" min="0.01" step="0.01" placeholder="0,00" required></label><label id="payment-frequency-field" hidden>Ödeme sıklığı<select name="frequency"><option value="monthly">Aylık</option><option value="weekly">Haftalık</option></select></label><label id="payment-start-field">İlk ödeme tarihi<input name="start_on" type="date" required></label><label id="payment-end-field"><span id="payment-end-label">Taksit bitiş tarihi</span><input name="end_on" type="date" required></label><label id="purchase-date-field" hidden>Alışveriş tarihi<input name="purchased_on" type="date" max="${day()}"></label><p id="payment-date-error" class="error field-wide" role="alert" hidden></p><div id="card-due-preview" class="date-summary field-wide" hidden></div></div><p class="entry-hint" id="payment-hint">Tutar her taksit içindir. Bitiş tarihindeki son ödeme de plana dahil edilir.</p><p class="error" id="payment-error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-close="payment-dialog">Vazgeç</button><button class="primary" type="submit">Kaydet</button></div></form></dialog>
<dialog id="income-dialog" class="entry-dialog"><form id="income-form">${dialogHead('＋','GELİRLERİM','<span id="income-title">Gelir ekle</span>','Gelirini ve ne zaman eline geçeceğini planla.')}<input name="request_key" type="hidden"><input name="id" type="hidden"><input name="record_kind" type="hidden"><input name="revision" type="hidden"><div class="entry-fields"><label class="field-wide">Gelir türü<select name="income_kind"><option value="once">Tek seferlik gelir</option><option value="recurring">Düzenli gelir</option></select></label><label class="field-wide">Açıklama<input name="description" placeholder="Örn. maaş, ek gelir, satış" maxlength="160" required></label><label class="field-wide amount-field">Tutar (₺)<input name="amount" type="number" inputmode="decimal" min="0.01" step="0.01" placeholder="0,00" required></label><label id="income-frequency-field" hidden>Tekrar sıklığı<select name="frequency"><option value="monthly">Aylık</option><option value="weekly">Haftalık</option></select></label><label id="income-date-field"><span id="income-date-label">Gelirin geldiği / geleceği tarih</span><input name="expected_on" type="date" required></label><label id="income-start-month-field" hidden>Başlangıç ayı<input name="start_month" type="month"></label><label id="income-status-field">Durum<select name="status"><option value="expected">Bekleniyor</option><option value="received">Alındı</option></select></label><label id="income-received-field" hidden>Gerçek alınma tarihi<input name="received_on" type="date" max="${day()}"></label><label id="month-end-field" class="checkbox-card field-wide" hidden><input name="end_of_month" type="checkbox"><span><b>Her ayın son günü</b><small>Şubat ve kısa aylar otomatik hesaplanır.</small></span></label></div><p class="entry-hint" id="income-hint">Beklenen gelir, alınmış gelir olarak sayılmaz.</p><p class="error" id="income-error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-close="income-dialog">Vazgeç</button><button class="primary" type="submit">Geliri kaydet</button></div></form></dialog>
<dialog id="paid-dialog" class="entry-dialog"><form id="paid-form">${dialogHead('✓','GERÇEKLEŞEN ÖDEME','Ödemeyi kaydet','Bu işlem yeni alışveriş oluşturmaz.')}<input name="event_id" type="hidden"><input name="request_key" type="hidden"><p id="paid-description"></p><label>Ödenen tutar (₺)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Gerçek ödeme tarihi<input name="paid_on" type="date" max="${day()}" required></label><p class="error" id="paid-error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-close="paid-dialog">Vazgeç</button><button class="primary" type="submit">Ödemeyi kaydet</button></div></form></dialog>
<dialog id="received-dialog" class="entry-dialog"><form id="received-form">${dialogHead('✓','TAHSİLAT','Gelirin alınmasını kaydet','Gelirin hesabına geçtiği günü seç.')}<input name="event_id" type="hidden"><p id="received-description"></p><label>Gerçek alınma tarihi<input name="received_on" type="date" max="${day()}" required></label><p class="error" id="received-error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-close="received-dialog">Vazgeç</button><button class="primary" type="submit">Alındı olarak kaydet</button></div></form></dialog>
<dialog id="card-dialog" class="entry-dialog"><form id="card-form">${dialogHead('▤','KREDİ KARTLARIM','Kredi kartı tanımı','Kart harcamalarının ödeme gününü buradan belirle.')}<input name="id" type="hidden"><input name="version" type="hidden"><label>Banka<input name="bank_name" maxlength="80" required></label><label>Kart adı<input name="display_name" maxlength="80" required></label><label>Son dört hane (isteğe bağlı)<input name="last_four" inputmode="numeric" pattern="[0-9]{4}" maxlength="4"></label><label>Son ödeme günü<input name="payment_due_day" type="number" min="1" max="31" step="1" placeholder="Örn. 9" required></label><label>Durum<select name="active"><option value="1">Aktif</option><option value="0">Pasif</option></select></label><small>Son ödeme günü tüm kart ödemelerinde kullanılır. 29–31 kısa aylarda ayın son gününe alınır. Aylık farkları ekstrede −5/+5 gün düzeltebilirsin. Gerçekleşmiş ödeme tarihleri korunur.</small><p class="error" id="card-error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-close="card-dialog">Vazgeç</button><button class="primary" type="submit">Kartı kaydet</button></div></form></dialog>`}
function updateIncomeFields(){const form=document.querySelector('#income-form'),recurring=form.elements.income_kind.value==='recurring',monthly=recurring&&form.elements.frequency.value==='monthly',last=monthly&&form.elements.end_of_month.checked;document.querySelector('#income-frequency-field').hidden=!recurring;document.querySelector('#income-status-field').hidden=recurring;form.elements.status.disabled=recurring;document.querySelector('#month-end-field').hidden=!monthly;document.querySelector('#income-date-field').hidden=last;form.elements.expected_on.disabled=last;form.elements.expected_on.required=!last;document.querySelector('#income-start-month-field').hidden=!last;form.elements.start_month.disabled=!last;form.elements.start_month.required=last;document.querySelector('#income-date-label').textContent=recurring?'İlk gelirin geleceği tarih':'Gelirin geldiği / geleceği tarih';document.querySelector('#income-hint').textContent=last?'Seçilen aydan başlayarak her ayın son günü planlanır.':recurring?(monthly?'Seçtiğin gün her ay tekrar eder; kısa aylarda ayın son günü kullanılır.':'İlk gelir gününden itibaren her 7 günde bir tekrar eder.'):'Beklenen gelir, alınmış gelir olarak sayılmaz.';const editing=Boolean(form.elements.id.value),record=editing&&form.elements.record_kind.value==='income_record',rule=editing&&form.elements.record_kind.value==='income_rule',source=rule?data.income_rules.find(row=>String(row.id)===form.elements.id.value):record?data.income_records.find(row=>String(row.id)===form.elements.id.value):null;form.elements.income_kind.disabled=editing;form.elements.frequency.disabled=false;form.elements.end_of_month.disabled=false;form.elements.expected_on.readOnly=false;form.elements.start_month.readOnly=false;const showReceived=record&&form.elements.status.value==='received';document.querySelector('#income-received-field').hidden=!showReceived;form.elements.received_on.disabled=!showReceived;form.elements.received_on.required=showReceived;if(showReceived&&!form.elements.received_on.value)form.elements.received_on.value=day();if(rule&&source?.has_receipts)document.querySelector('#income-hint').textContent='Tutar değişikliği bugünden sonraki beklenen gelirlere uygulanır; alınmış gelirler korunur. Gün ve sıklık değişikliğinde başlangıcı bugün veya sonrası seç. Gerçekleşen tahsilatlar ayrı kayıtlarda korunur.';if(record&&source?.rule_id)document.querySelector('#income-hint').textContent='Bu tahsilatın tutarını ve gerçek alınma tarihini düzeltebilirsin. Plan tarihini değiştirirsen bu kayıt tek seferlik ayrılır; eski tarihte ikinci gelir oluşmaz.';}
function updatePaymentFields(){const form=document.querySelector('#payment-form'),expense=form.elements.entry_kind.value==='expense',regular=form.elements.entry_kind.value==='regular',card=profile?.cards.find(card=>card.id===form.elements.card_ref.value),summary=document.querySelector('#card-due-preview');const cardLinked=Boolean(card)&&!expense;for(const name of ['start_on','end_on']){const field=form.elements[name],value=field.value;field.type=cardLinked?'month':'date';field.value=cardLinked?value.slice(0,7):value.length===7?value+'-01':value;}document.querySelector('#payment-start-field').firstChild.textContent=cardLinked?'İlk ödeme ayı':'İlk ödeme tarihi';document.querySelector('#payment-end-field span').textContent=cardLinked?'Son ödeme ayı':'Son ödeme tarihi';document.querySelector('#payment-frequency-field').hidden=!regular;form.elements.frequency.disabled=!regular;document.querySelector('#payment-card-field').hidden=false;form.elements.card_ref.disabled=false;form.elements.card_ref.options[0].textContent=regular?'Nakit / banka kartı':form.elements.id.value?'Kart seçilmedi':'Kredi kartı seç';document.querySelector('#payment-end-label').textContent=cardLinked?'Son ödeme ayı':regular?'Son ödeme tarihi':'Taksit bitiş tarihi';document.querySelector('#payment-start-field').hidden=expense;document.querySelector('#payment-end-field').hidden=expense;form.elements.start_on.disabled=expense;form.elements.start_on.required=!expense;form.elements.end_on.disabled=expense;form.elements.end_on.required=!expense;document.querySelector('#purchase-date-field').hidden=!expense;form.elements.purchased_on.disabled=!expense;form.elements.purchased_on.required=expense;form.elements.card_ref.required=expense||(!regular&&!form.elements.id.value);document.querySelector('#payment-amount-label').textContent=expense?'Harcama tutarı (₺)':regular?'Ödeme tutarı (₺)':'Aylık taksit tutarı (₺)';summary.hidden=!card;summary.innerHTML=card?.payment_due_day?`<small>KARTIN SON ÖDEME GÜNÜ</small><strong>Her ayın ${card.payment_due_day}. günü</strong><span>${esc(cardLabel(card.id))}</span>`:'<span>Ödeme gününü görmek için son ödeme tarihi tanımlı bir kart seç.</span>';document.querySelector('#payment-hint').textContent=expense?'Tek seferlik kaydedilir. Ödeme günü seçilen kartın ayarından alınır; alışveriş bugün nakit çıkışı sayılmaz.':regular?'Banka kartı / nakit seçebilir veya kredi kartını belirtebilirsin. Girdiğin tarih bankadan ödeme yapacağın gündür. Haftalık 7 günde bir, aylık aynı gün tekrarlanır; bitişten sonra ödeme oluşmaz.':'Tutar her taksit içindir. Bitiş tarihindeki son ödeme de plana dahil edilir.';form.elements.end_on.min=form.elements.start_on.value;const invalid=!expense&&form.elements.end_on.value&&form.elements.start_on.value&&form.elements.end_on.value<form.elements.start_on.value,dateError=document.querySelector('#payment-date-error'),message=invalid?`Son ödeme tarihi (${form.elements.end_on.value.length===7?monthLabel(form.elements.end_on.value):dateLabel(form.elements.end_on.value)}), ilk ödeme tarihinden (${form.elements.start_on.value.length===7?monthLabel(form.elements.start_on.value):dateLabel(form.elements.start_on.value)}) önce olamaz. Bitiş yılını kontrol et.`:'';form.elements.end_on.setCustomValidity(message);dateError.textContent=message;dateError.hidden=!invalid;if(data.rules.find(row=>String(row.id)===form.elements.id.value)?.has_paid)document.querySelector('#payment-hint').textContent+=' Ödeme geçmişi bulunan planın tutarı, günü ve kartı korunur; açıklamasını düzenleyebilir veya hatalı kaydı Sil ile geri alınabilir biçimde kaldırabilirsin.';}
function render(){const title={overview:'Genel Bakış',payments:'Ödemelerim',income:'Gelirlerim',profile:'Profil ve Ayarlar'}[section];root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">₺</span><div><b>Harcama Takibi</b><small>KİŞİSEL BÜTÇE</small></div></div><nav aria-label="Ana gezinme">${[['overview','◷','Genel Bakış'],['payments','↗','Ödemelerim'],['income','＋','Gelirlerim'],['profile','⚙','Profil ve Ayarlar']].map(([id,icon,label])=>`<a href="#${id}" data-section="${id}" ${section===id?'aria-current="page"':''}>${icon}　${label}</a>`).join('')}</nav><div class="side-bottom"><button class="profile-switch" id="open-profile"><b>${esc(profile?.display_name||'Profil')}</b><small>${esc(profile?.email||'Hesap bilgileri')}</small></button><button class="link" id="logout">Çıkış yap ↗</button></div></aside><main class="content"><header><div><p class="eyebrow">GELİR · ÖDEME · KALAN</p><h1>${title}</h1><p class="muted">${section==='overview'?esc(monthLabel(selectedMonth)):dateLabel(start)+' – '+dateLabel(end)}</p></div>${themeToggleMarkup()}</header>${section==='overview'?'<details class="overall-range"><summary>Genel toplamların tarih aralığını değiştir</summary>':''}<section class="simple-period"><label>Başlangıç<input id="period-start" type="date" value="${start}"></label><label>Bitiş<input id="period-end" type="date" value="${end}"></label><button class="secondary compact" id="show-period">Göster</button><button class="link" id="three-months">Önümüzdeki 3 ay</button><button class="link" id="all-payments">Tüm taksitler</button></section>${section==='overview'?'</details>':''}<p class="error-banner" id="action-error" role="alert"></p><p class="success-note" id="success" role="status"></p>${data.local_sandbox?'<p class="success-note"><b>Yerel çalışma kopyası.</b> Değişiklikleri burada deneyebilirsin; canlı hesabına aktarılmaz.</p>':''}${data.read_only_preview?'<p class="success-note"><b>Yerel, salt okunur önizleme.</b> Gerçek hesabından okunan veriler gösteriliyor. Buradaki işlemler canlı kayıtlara kaydedilmez.</p>':''}${section==='overview'?overviewMarkup():section==='payments'?paymentsMarkup():section==='profile'?profileMarkup():incomeMarkup()}</main></div>${dialogs()}`;bind()}
function openIncome(row,kind='income_record'){const form=document.querySelector('#income-form');form.reset();form.elements.id.value=row?.id||'';form.elements.record_kind.value=row?kind:'';form.elements.revision.value=row?.revision||'';form.elements.request_key.value=crypto.randomUUID();const rule=row&&kind==='income_rule';form.elements.income_kind.value=rule?'recurring':'once';form.elements.description.value=row?.description||'';form.elements.amount.value=row?inputMoney(row.amount_minor):'';form.elements.frequency.value=rule&&row.frequency==='weekly'?'weekly':'monthly';form.elements.expected_on.value=row?(rule?row.start_on:row.expected_on):day();form.elements.start_month.value=(rule?row.start_on:day()).slice(0,7);form.elements.end_of_month.checked=Boolean(rule&&row.schedule_mode==='last_day');form.elements.status.value=!rule&&row?.status==='received'?'received':'expected';form.elements.received_on.value=row?.received_on||day();document.querySelector('#income-title').textContent=row?(rule?'Düzenli geliri düzenle':'Geliri düzenle'):'Gelir ekle';document.querySelector('#income-error').textContent='';updateIncomeFields();document.querySelector('#income-dialog').showModal()}
function openPayment(rule){const form=document.querySelector('#payment-form');form.reset();form.elements.start_on.type='date';form.elements.end_on.type='date';form.elements.id.value=rule?.id||'';form.elements.request_key.value=crypto.randomUUID();form.elements.entry_kind.value=rule?.entry_kind||'installment';form.elements.frequency.value=rule?.frequency==='weekly'?'weekly':'monthly';form.elements.description.value=rule?.description||'';form.elements.amount.value=rule?inputMoney(rule.amount_minor):'';form.elements.start_on.value=rule?.start_on||day();form.elements.end_on.value=rule?.end_on||'';form.elements.purchased_on.value=rule?.purchased_on||day();form.elements.card_ref.innerHTML='<option value="">Banka / nakit (kart kullanmadan)</option>'+(profile?.cards||[]).filter(card=>card.active||card.id===rule?.card_ref).map(card=>`<option value="${esc(card.id)}">${esc(cardLabel(card.id))}${card.active?'':' · Pasif'}</option>`).join('');form.elements.card_ref.value=rule?.card_ref||'';document.querySelector('#payment-title').textContent=rule?'Kaydı düzenle':'Taksit / harcama ekle';document.querySelector('#payment-error').textContent='';updatePaymentFields();document.querySelector('#payment-dialog').showModal()}
async function submit(form,errorId,operation){const button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;document.querySelector(errorId).textContent='';try{await operation();form.closest('dialog').close();await load();const message=document.querySelector('#success');if(message)message.textContent='Kaydedildi.'}catch(error){document.querySelector(errorId).textContent=error.message}finally{button.disabled=false}}
function bind(){const openingButton=document.querySelector('#new-opening');if(openingButton)openingButton.onclick=()=>{const form=document.querySelector('#opening-form');form.reset();const position=monthlyData?.cash_position||data.cash_position;form.elements.amount.value=position?.configured?inputMoney(position.opening_balance_minor):'';form.elements.effective_on.value=position?.effective_on||day();form.elements.revision.value=position?.revision||'';document.querySelector('#opening-error').textContent='';document.querySelector('#opening-dialog').showModal()};document.querySelector('#opening-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#opening-error',()=>api('/api/simple-opening',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))}))};const monthInput=document.querySelector('#overview-month');if(monthInput){monthInput.onchange=()=>{if(/^\d{4}-\d{2}$/.test(monthInput.value)){selectedMonth=monthInput.value;load()}};document.querySelector('#previous-month').onclick=()=>shiftOverviewMonth(-1);document.querySelector('#next-month').onclick=()=>shiftOverviewMonth(1);document.querySelector('#current-month').onclick=()=>{selectedMonth=day().slice(0,7);load()}};document.querySelector('#open-profile').onclick=()=>{section='profile';history.replaceState(null,'','#profile');render()};if(data.read_only_preview){document.querySelectorAll('form:not(#auth-form) button[type=submit],[data-rule-status]').forEach(button=>{button.disabled=true;button.title='Salt okunur önizlemede kayıt değiştirme kapalı'})}document.querySelectorAll('[data-section]').forEach(link=>link.onclick=event=>{event.preventDefault();section=link.dataset.section;history.replaceState(null,'','#'+section);render()});document.querySelector('#logout').onclick=async()=>{await api('/api/logout',{method:'POST',body:'{}'});csrf='';authView()};document.querySelector('#show-period').onclick=()=>{start=document.querySelector('#period-start').value;end=document.querySelector('#period-end').value;load()};document.querySelector('#three-months').onclick=()=>{start=day().slice(0,7)+'-01';end=plusMonths(day(),3);load()};document.querySelector('#all-payments').onclick=()=>{start=day().slice(0,7)+'-01';end=data.rules.filter(rule=>rule.status==='active'&&rule.end_on).map(rule=>rule.end_on).sort().at(-1)||plusMonths(day(),12);load()};document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.close).close());document.querySelectorAll('[data-card-total]').forEach(form=>{form.elements.due_day_offset.onchange=()=>{const card=(cardDebtData||monthlyData).card_monthly_debt.cards.find(row=>row.card_ref===form.dataset.cardTotal);form.querySelector('output').textContent=dateLabel(cardDuePreview(card,(cardDebtData||monthlyData).card_monthly_debt.month,Number(form.elements.due_day_offset.value)));};form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button'),error=form.querySelector('.error'),card=(cardDebtData||monthlyData).card_monthly_debt.cards.find(row=>row.card_ref===form.dataset.cardTotal);if(button.disabled)return;button.disabled=true;button.textContent='Kaydediliyor…';error.textContent='';try{await api('/api/simple-card-monthly-total',{method:'PUT',body:JSON.stringify({card_ref:card.card_ref,month:(cardDebtData||monthlyData).card_monthly_debt.month,source_month:card.source_month,due_day_offset:Number(form.elements.due_day_offset.value),amount:form.elements.amount.value,version:card.version})});chooseDebtMonth((cardDebtData||monthlyData).card_monthly_debt.month);await load();document.querySelector('#success').textContent='Aylık kart borcu kaydedildi.'}catch(problem){error.textContent=problem.message;button.disabled=false;button.textContent='Borcu kaydet'}}});const spendingMonth=document.querySelector('#spending-month');if(spendingMonth)spendingMonth.onchange=()=>{if(/^\d{4}-\d{2}$/.test(spendingMonth.value)){chooseDebtMonth(spendingMonth.value);load()}};const newExtra=document.querySelector('#new-extra');if(newExtra)newExtra.onclick=()=>{openPayment();const form=document.querySelector('#payment-form');form.elements.entry_kind.value='expense';updatePaymentFields()};const newPayment=document.querySelector('#new-payment');if(newPayment)newPayment.onclick=()=>openPayment();document.querySelectorAll('[data-edit-rule]').forEach(button=>button.onclick=()=>openPayment(data.rules.find(rule=>String(rule.id)===button.dataset.editRule)));document.querySelectorAll('[data-rule-status]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/api/recurring/${button.dataset.ruleStatus}/status`,{method:'POST',body:JSON.stringify({status:button.dataset.status})});await load()}catch(error){document.querySelector('#action-error').textContent=error.message;button.disabled=false}});
 const profileForm=document.querySelector('#profile-form');if(profileForm){const input=profileForm.elements.display_name,button=profileForm.querySelector('button[type=submit]'),saved=profile.display_name;const update=()=>{const dirty=input.value.trim()!==saved&&input.value.trim().length>0&&!data.read_only_preview;button.disabled=!dirty;button.classList.toggle('primary',dirty);button.classList.toggle('secondary',!dirty);};input.addEventListener('input',update);update();profileForm.onsubmit=async event=>{event.preventDefault();if(button.disabled)return;button.disabled=true;button.textContent='Kaydediliyor…';profileForm.setAttribute('aria-busy','true');try{await api('/api/profile',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(profileForm)))});await load();document.querySelector('#success').textContent='Profil kaydedildi.'}catch(error){const target=document.querySelector('#profile-error');if(target)target.textContent=error.message;button.textContent='Profili kaydet';update();}finally{profileForm.setAttribute('aria-busy','false')}};}
 const newCard=document.querySelector('#new-card');if(newCard)newCard.onclick=()=>openCard();document.querySelectorAll('[data-edit-profile-card]').forEach(button=>button.onclick=()=>openCard(profile.cards.find(card=>card.id===button.dataset.editProfileCard)));document.querySelector('#card-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#card-error',async()=>{const payload=Object.fromEntries(new FormData(form));payload.version=Number(payload.version);payload.active=Number(payload.active);await api('/api/profile/cards',{method:'POST',body:JSON.stringify(payload)})})};
 const paymentForm=document.querySelector('#payment-form');paymentForm.elements.entry_kind.onchange=updatePaymentFields;paymentForm.elements.start_on.oninput=updatePaymentFields;paymentForm.elements.end_on.oninput=updatePaymentFields;paymentForm.elements.card_ref.onchange=()=>{const card=profile?.cards.find(card=>card.id===paymentForm.elements.card_ref.value);if(card?.payment_due_on&&!paymentForm.elements.id.value&&paymentForm.elements.entry_kind.value==='installment')paymentForm.elements.start_on.value=card.payment_due_on;updatePaymentFields()};paymentForm.onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#payment-error',async()=>{const payload=Object.fromEntries(new FormData(form)),old=data.rules.find(rule=>String(rule.id)===payload.id);if(payload.card_ref){const card=profile.cards.find(card=>card.id===payload.card_ref);for(const field of ['start_on','end_on'])if(payload[field]?.length===7)payload[field]=cardDuePreview(card,payload[field]);}payload.frequency=payload.entry_kind==='regular'?form.elements.frequency.value:old?.frequency||'monthly';if(old){payload.category_id=old.category_id;payload.payment_method_id=old.payment_method_id;payload.revision=old.revision}if(payload.entry_kind==='expense'){const card=profile.cards.find(card=>card.id===payload.card_ref);if(!card?.payment_due_on)throw Error('Kartın son ödeme tarihini Profil ve Ayarlar bölümünden gir.');delete payload.start_on;}await api('/api/simple-payment-plans',{method:'POST',body:JSON.stringify(payload)})})};
 const newIncome=document.querySelector('#new-income');if(newIncome)newIncome.onclick=()=>openIncome();document.querySelectorAll('[data-edit-income]').forEach(button=>button.onclick=()=>{const kind=button.dataset.incomeKind,row=(kind==='income_rule'?data.income_rules:data.income_records).find(row=>String(row.id)===button.dataset.editIncome);openIncome(row,kind)});const incomeForm=document.querySelector('#income-form');for(const name of ['income_kind','frequency','end_of_month','status'])incomeForm.elements[name].onchange=updateIncomeFields;incomeForm.onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#income-error',async()=>{const payload=Object.fromEntries(new FormData(form)),recurring=form.elements.income_kind.value==='recurring',editing=Boolean(form.elements.id.value);payload.frequency=recurring?form.elements.frequency.value:'once';payload.schedule_mode=recurring&&payload.frequency==='monthly'&&form.elements.end_of_month.checked?'last_day':'anchored';if(payload.schedule_mode==='last_day'){payload.start_month=form.elements.start_month.value;if(editing)payload.expected_on=payload.start_month+'-01';else{delete payload.expected_on;delete payload.start_on;}}await api('/api/simple-income',{method:editing?'PUT':'POST',body:JSON.stringify(payload)})})};
 document.querySelectorAll('[data-delete-kind]').forEach(button=>button.onclick=()=>{const kind=button.dataset.deleteKind,list=kind==='payment_plan'?data.rules:kind==='income_rule'?data.income_rules:data.income_records,row=list.find(row=>String(row.id)===button.dataset.recordId),form=document.querySelector('#delete-form');form.reset();form.elements.record_kind.value=kind;form.elements.id.value=row.id;form.elements.revision.value=kind==='payment_plan'?row.deletion_revision:row.revision;document.querySelector('#delete-name').textContent=row.description;document.querySelector('#delete-impact').textContent=kind==='income_rule'?'Bu düzenli gelir planı ve ona bağlı tüm tahsilat kayıtları hesaplamalardan çıkarılacak. Mevcut banka bakiyesi ve tahmin yeniden hesaplanacak.':kind==='payment_plan'?'Bu harcama / ödeme planı ve ona bağlı gerçekleşen ödemeler hesaplamalardan çıkarılacak. Ayrı girdiğin toplam kart borcu ve kart ödemeleri korunacak.':'Bu gelir hesabından kaldırılacak. Alınmış bir gelir ise banka bakiyesindeki etkisi de geri alınacak.';document.querySelector('#delete-error').textContent='';document.querySelector('#delete-dialog').showModal()});document.querySelector('#delete-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;try{const deleted=await api('/api/simple-records/delete',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),confirmation:'SİL'})});document.querySelector('#delete-dialog').close();await load();const note=document.querySelector('#success');note.innerHTML='Kayıt silindi. <button class="link" id="undo-delete">Geri al</button>';document.querySelector('#undo-delete').onclick=async()=>{const undo=document.querySelector('#undo-delete');undo.disabled=true;try{await api('/api/simple-records/restore',{method:'POST',body:JSON.stringify(deleted)});await load();document.querySelector('#success').textContent='Kayıt geri alındı.'}catch(problem){document.querySelector('#action-error').textContent=problem.message;undo.disabled=false}}}catch(problem){document.querySelector('#delete-error').textContent=problem.message;button.disabled=false}};
 document.querySelectorAll('[data-pay]').forEach(button=>button.onclick=()=>{const event=findEvent(button.dataset.pay),form=document.querySelector('#paid-form');form.reset();form.elements.event_id.value=event.id;form.elements.request_key.value=crypto.randomUUID();form.elements.amount.value=inputMoney(event.amount_minor);form.elements.paid_on.value=day();document.querySelector('#paid-description').textContent=event.description+' · Planlanan '+dateLabel(event.date);document.querySelector('#paid-error').textContent='';document.querySelector('#paid-dialog').showModal()});document.querySelector('#paid-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#paid-error',async()=>{const payload=Object.fromEntries(new FormData(form)),row=findEvent(payload.event_id);payload.scheduled_on=row.scheduled_on;if(row.monthly_card_ref){payload.card_ref=row.monthly_card_ref;payload.month=row.monthly_month;await api('/api/simple-card-monthly-payments',{method:'POST',body:JSON.stringify(payload)})}else if(row.statement_id){payload.statement_id=row.statement_id;await api('/api/simple-statement-payments',{method:'POST',body:JSON.stringify(payload)})}else await api(`/api/simple-payments/${row.recurring_id}/complete`,{method:'POST',body:JSON.stringify(payload)})})};
 document.querySelectorAll('[data-receive]').forEach(button=>button.onclick=()=>{const row=findEvent(button.dataset.receive),form=document.querySelector('#received-form');form.reset();form.elements.event_id.value=row.id;form.elements.received_on.value=day();document.querySelector('#received-description').textContent=row.description;document.querySelector('#received-error').textContent='';document.querySelector('#received-dialog').showModal()});document.querySelector('#received-form').onsubmit=event=>{event.preventDefault();const form=event.target;submit(form,'#received-error',async()=>{const row=findEvent(form.elements.event_id.value);await api('/api/simple-income/receive',{method:'POST',body:JSON.stringify({record_id:row.record_id,rule_id:row.rule_id,scheduled_on:row.scheduled_on,expected_amount_minor:row.amount_minor,received_on:form.elements.received_on.value})})})};}
(async()=>{try{const session=await api('/api/session');privateBeta=Boolean(session.private_beta);if(!session.user_id){authView();return}csrf=session.csrf;const hash=location.hash.slice(1);if(['overview','payments','income','profile'].includes(hash))section=hash;await load()}catch(error){authView()}})();
